package fi.rosu.afkroulette;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(AfkRouletteConfig.GROUP)
public interface AfkRouletteConfig extends Config
{
	String GROUP = "afkroulette";
	String PRIVACY_URL = "https://afk.rosu.fi/privacy.html";
	String SERVER_WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	@ConfigItem(
		keyName = "serverEnabled",
		name = "Connect to AFK Roulette server",
		description = "Roll tasks and view your group from the AFK Roulette server (afk.rosu.fi). "
			+ "Sends your IP address, your RuneScape name and your task results (completions and skips, "
			+ "derived from xp drops, kill counts, collection log, diary and quest messages). "
			+ "Privacy policy: " + PRIVACY_URL,
		warning = SERVER_WARNING,
		position = 0
	)
	default boolean serverEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "shareData",
		name = "Share my data with the group",
		description = "Additionally uploads your levels, xp, quest states, inventory, equipment, bank, seed vault, "
			+ "current world and an online heartbeat so your group can see them. Turning this off "
			+ "(or leaving the group) removes your shared data from the group. "
			+ "Privacy policy: " + PRIVACY_URL,
		warning = SERVER_WARNING,
		position = 1
	)
	default boolean shareData()
	{
		return false;
	}

	@ConfigItem(
		keyName = "groupToken",
		name = "Group token",
		description = "Your group's token. Create or join a group in the panel's Group tab (or use /plugin in the AFK Roulette Discord bot).",
		secret = true,
		position = 2
	)
	default String groupToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "rollAnimation",
		name = "Roll animation",
		description = "Spin a reel of icons over the game view when you roll a task",
		position = 3
	)
	default boolean rollAnimation()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rollSound",
		name = "Roll sounds",
		description = "Play ticking and a chime while the roll reel spins (uses the game's sound effect volume)",
		position = 4
	)
	default boolean rollSound()
	{
		return true;
	}
}

package fi.rosu.afkroulette;

import com.google.inject.Provides;
import fi.rosu.afkroulette.reel.RollOverlay;
import fi.rosu.afkroulette.sync.SyncManager;
import fi.rosu.afkroulette.tracker.TaskTracker;
import fi.rosu.afkroulette.ui.AfkRoulettePanel;
import java.awt.image.BufferedImage;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "AFK Roulette",
	description = "Task roulette plus a group tracker: shared stats, gear and item search",
	tags = {"task", "tasker", "roulette", "afk", "group", "ironman", "gim", "items", "search"}
)
public class AfkRoulettePlugin extends Plugin
{
	private static final Set<String> USER_SETTINGS = Set.of("serverEnabled", "shareData", "groupToken");
	private static final int INVENTORY_SLOTS = 28;
	private static final int EQUIPMENT_SLOTS = 14;
	/** Containers whose slot order matters (shown as grids); others are sent compacted. */
	private static final int COMPACT = -1;

	@Inject
	private Client client;
	@Inject
	private AfkRouletteConfig config;
	@Inject
	private GroupLeaver leaver;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ItemManager itemManager;
	@Inject
	private SyncManager sync;
	@Inject
	private PlayerState player;
	@Inject
	private TaskTracker tracker;
	@Inject
	private EventBus eventBus;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private RollOverlay rollOverlay;
	@Inject
	private ConfigManager configManager;

	private AfkRoulettePanel panel;
	private NavigationButton navButton;
	/** Game ticks until a full quest/skill snapshot is taken after login. */
	private int snapshotInTicks = -1;
	/** The RuneLite config profile in use: switching profiles is not the user changing settings. */
	private long configProfileId;

	@Override
	protected void startUp()
	{
		panel = injector.getInstance(AfkRoulettePanel.class);
		BufferedImage icon = ImageUtil.loadImageResource(AfkRoulettePlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("AFK Roulette")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(rollOverlay);
		configProfileId = currentConfigProfileId();
		eventBus.register(tracker);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			snapshotInTicks = 2;
		}
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(tracker);
		clientThread.invoke(tracker::reset);
		overlayManager.remove(rollOverlay);
		rollOverlay.stop();
		panel.onShutdown();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		sync.reset();
		player.setName(null);
		snapshotInTicks = -1;
	}

	@Provides
	AfkRouletteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AfkRouletteConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			snapshotInTicks = 3;
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			player.setName(null);
			tracker.reset();
			if (panel != null)
			{
				panel.onPlayerChanged();
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Player local = client.getLocalPlayer();
		if (local != null && local.getName() != null)
		{
			String name = PlayerState.normalize(local.getName());
			if (!name.equals(player.getName()))
			{
				player.setName(name);
				tracker.refresh();
				if (panel != null)
				{
					panel.onPlayerChanged();
				}
			}
		}
		if (snapshotInTicks > 0 && --snapshotInTicks == 0)
		{
			tracker.baseline();
			collectSkills();
			collectQuests();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		collectSkills();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!sharing())
		{
			return;
		}
		String name = trackedName();
		if (name == null)
		{
			return;
		}
		ItemContainer container = event.getItemContainer();
		int id = event.getContainerId();
		if (id == InventoryID.INV)
		{
			sync.update(name, "inventory", flatItems(container, INVENTORY_SLOTS));
		}
		else if (id == InventoryID.WORN)
		{
			sync.update(name, "equipment", flatItems(container, EQUIPMENT_SLOTS));
		}
		else if (id == InventoryID.BANK)
		{
			sync.update(name, "bank", flatItems(container, COMPACT));
		}
		else if (id == InventoryID.SEED_VAULT)
		{
			sync.update(name, "seed_vault", flatItems(container, COMPACT));
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Only the user's settings: the tracker's own progress saves (RS-profile keys
		// in the same group) must not reload everything.
		if (AfkRouletteConfig.GROUP.equals(event.getGroup()) && panel != null
			&& USER_SETTINGS.contains(event.getKey()))
		{
			removeSharedDataIfStopped(event);
			sync.resendAll();
			tracker.refresh();
			panel.onConfigChanged();
			// Nothing is collected while sharing is off, so take a fresh snapshot when it turns on.
			clientThread.invokeLater(() ->
			{
				collectSkills();
				collectQuests();
			});
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// May be posted from any thread; the tracker lives on the client thread.
		String previous = event.getPreviousProfile();
		clientThread.invoke(() ->
		{
			// Logging in (no previous profile) is handled by the login snapshot.
			if (previous == null)
			{
				return;
			}
			// Saved task progress is per RS profile: keep the old one's, start over and re-baseline.
			tracker.resetForNewProfile(previous);
			snapshotInTicks = 2;
			tracker.refresh();
		});
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		configProfileId = currentConfigProfileId();
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		tracker.saveNow();
	}

	private long currentConfigProfileId()
	{
		return configManager.getProfile() == null ? 0 : configManager.getProfile().getId();
	}

	/**
	 * Sharing turned off, or the group token replaced: the snapshot already uploaded under the
	 * old token is removed from that group (fire and forget). Tasks and streaks there stay.
	 */
	private void removeSharedDataIfStopped(ConfigChanged event)
	{
		// A RuneLite profile switch also reports every differing setting as changed.
		if (currentConfigProfileId() != configProfileId)
		{
			return;
		}
		if ("shareData".equals(event.getKey()))
		{
			if (Boolean.parseBoolean(event.getOldValue()) && !Boolean.parseBoolean(event.getNewValue()))
			{
				leaver.leave(config.groupToken(), true);
			}
		}
		else if ("groupToken".equals(event.getKey()))
		{
			String oldToken = event.getOldValue() == null ? "" : event.getOldValue().trim();
			String newToken = event.getNewValue() == null ? "" : event.getNewValue().trim();
			if (!oldToken.isEmpty() && !oldToken.equals(newToken))
			{
				leaver.leave(oldToken, true);
			}
		}
	}

	/** Quest states rarely change; also acts as a once-a-minute "online" heartbeat. */
	@Schedule(period = 60, unit = ChronoUnit.SECONDS)
	public void refreshQuests()
	{
		collectQuests();
		// Picks up tasks rolled, skipped or finished on Discord or the website.
		if (trackedName() != null)
		{
			tracker.refresh();
		}
	}

	@Schedule(period = 2, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void upload()
	{
		sync.submit(player.getName());
	}

	/** Whether anything may be uploaded: the server is on and the player chose to share. */
	private boolean sharing()
	{
		return config.serverEnabled() && config.shareData();
	}

	private void collectSkills()
	{
		if (!sharing())
		{
			return;
		}
		String name = trackedName();
		if (name == null)
		{
			return;
		}
		Map<String, Integer> levels = new HashMap<>();
		Map<String, Integer> xp = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			levels.put(skill.getName(), client.getRealSkillLevel(skill));
			xp.put(skill.getName(), client.getSkillExperience(skill));
		}
		sync.update(name, "levels", levels);
		sync.update(name, "xp", xp);
	}

	private void collectQuests()
	{
		// The tracker reads the quest log whenever the server is on; only uploading needs sharing.
		if (!config.serverEnabled())
		{
			return;
		}
		String name = trackedName();
		if (name == null)
		{
			return;
		}
		Map<String, String> quests = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			quests.put(quest.getName(), quest.getState(client).name());
		}
		tracker.onQuestStates(quests);
		if (!config.shareData())
		{
			return;
		}
		sync.update(name, "quests", quests);
		sync.update(name, "world", client.getWorld());
		sync.update(name, "heartbeat", System.currentTimeMillis() / 60_000);

		// Container events only fire on change; read them directly too, so a plugin
		// started mid-session (or events that came before login finished) still sync.
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			sync.update(name, "inventory", flatItems(inventory, INVENTORY_SLOTS));
		}
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			sync.update(name, "equipment", flatItems(worn, EQUIPMENT_SLOTS));
		}
	}

	/** The player whose data may be collected right now, or null. */
	private String trackedName()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return null;
		}
		// Leagues, Deadman etc. are separate accounts in practice; never mix them with the main game.
		if (RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD)
		{
			return null;
		}
		return PlayerState.normalize(client.getLocalPlayer().getName());
	}

	/** [id, qty, id, qty, ...] with noted items canonicalized so searches count them too. */
	private List<Integer> flatItems(ItemContainer container, int slots)
	{
		List<Integer> out = new ArrayList<>();
		if (slots == COMPACT)
		{
			for (Item item : container.getItems())
			{
				if (isRealItem(item))
				{
					out.add(itemManager.canonicalize(item.getId()));
					out.add(item.getQuantity());
				}
			}
			return out;
		}
		for (int i = 0; i < slots; i++)
		{
			Item item = container.getItem(i);
			if (isRealItem(item))
			{
				out.add(itemManager.canonicalize(item.getId()));
				out.add(item.getQuantity());
			}
			else
			{
				out.add(0);
				out.add(0);
			}
		}
		return out;
	}

	private boolean isRealItem(Item item)
	{
		return item != null && item.getId() > 0 && item.getQuantity() > 0
			&& itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() == -1;
	}
}

package fi.rosu.afkroulette;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Talks to the AFK Roulette server. Every call is asynchronous (OkHttp's own
 * thread pool) and the callback runs on that pool, never on the client thread.
 */
@Slf4j
@Singleton
public class ApiClient
{
	public static final String BASE_URL = "https://afk-api.rosu.fi";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	/** Larger responses are cut short and fail to parse instead of exhausting memory. */
	private static final long MAX_RESPONSE_BYTES = 4_000_000;

	public interface Callback
	{
		/**
		 * @param body  parsed JSON body (may be present also on errors)
		 * @param error null on success, otherwise a short human readable reason
		 */
		void onResult(JsonObject body, String error);
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final AfkRouletteConfig config;

	@Inject
	ApiClient(OkHttpClient http, Gson gson, AfkRouletteConfig config)
	{
		this.http = http;
		this.gson = gson;
		this.config = config;
	}

	public void get(String path, Map<String, String> query, Callback cb)
	{
		get(path, query, null, cb);
	}

	/** GET with an explicit group token instead of the configured one (e.g. to check a token before saving it). */
	public void get(String path, Map<String, String> query, String tokenOverride, Callback cb)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + path);
		if (base == null)
		{
			cb.onResult(null, "Bad URL");
			return;
		}
		HttpUrl.Builder url = base.newBuilder();
		if (query != null)
		{
			query.forEach(url::addQueryParameter);
		}
		send(new Request.Builder().url(url.build()).get(), tokenOverride, cb);
	}

	public void post(String path, Object body, Callback cb)
	{
		post(path, body, null, cb);
	}

	/** POST with an explicit group token instead of the configured one. */
	public void post(String path, Object body, String tokenOverride, Callback cb)
	{
		RequestBody requestBody = RequestBody.create(JSON, gson.toJson(body));
		send(new Request.Builder().url(BASE_URL + path).post(requestBody), tokenOverride, cb);
	}

	private void send(Request.Builder request, String tokenOverride, Callback cb)
	{
		if (!config.serverEnabled())
		{
			cb.onResult(null, "Server connection is off. Turn it on in the plugin settings.");
			return;
		}
		String token = tokenOverride != null ? tokenOverride.trim() : config.groupToken().trim();
		if (!token.isEmpty())
		{
			// A pasted token with stray characters would make OkHttp throw on the header.
			if (!isValidToken(token))
			{
				cb.onResult(null, "Invalid group token");
				return;
			}
			request.header("Authorization", token);
		}
		request.header("Accept", "application/json");

		http.newCall(request.build()).enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("AFK Roulette request failed", e);
				cb.onResult(null, "Could not reach the server");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				JsonObject json;
				String error;
				try (Response r = response)
				{
					JsonObject parsed = parse(r.peekBody(MAX_RESPONSE_BYTES).string());
					json = parsed;
					if (r.isSuccessful())
					{
						error = parsed == null ? "Unexpected server response" : null;
					}
					else
					{
						JsonElement e = parsed != null ? parsed.get("error") : null;
						error = e != null && e.isJsonPrimitive() ? e.getAsString() : "Server error " + r.code();
					}
				}
				catch (IOException | RuntimeException e)
				{
					log.debug("AFK Roulette response read failed", e);
					json = null;
					error = "Could not read the server response";
				}
				// Every request gets exactly one answer, so callers never stay "busy".
				cb.onResult(json, error);
			}
		});
	}

	/** Tokens are URL-safe base64 from the server. */
	public static boolean isValidToken(String token)
	{
		return token.matches("[A-Za-z0-9_-]{8,128}");
	}

	private JsonObject parse(String text)
	{
		try
		{
			return gson.fromJson(text, JsonObject.class);
		}
		catch (JsonParseException e)
		{
			return null;
		}
	}
}

package fi.rosu.afkroulette;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Experience;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * Latest snapshot of the group's shared data, used by the Group and Items tabs.
 */
@Slf4j
@Singleton
public class GroupData
{
	public static final String[] CONTAINERS = {"inventory", "equipment", "bank", "seed_vault"};
	private static final int MAX_ITEM_ID = 65535;
	/** Item names resolved per refresh; ids come from other clients, so the work is bounded. */
	private static final int MAX_LOOKUPS = 5000;

	public static final class Member
	{
		@Getter
		private final String nick;
		/** Seconds since the member's client last uploaded, by the server's clock. */
		@Getter
		private final long secondsAgo;
		@Getter
		private final Map<String, Integer> levels;
		/** container -> flat [id, qty, id, qty, ...] (inventory/equipment keep slot order). */
		private final Map<String, int[]> containers;

		Member(String nick, long secondsAgo, Map<String, Integer> levels, Map<String, int[]> containers)
		{
			this.nick = nick;
			this.secondsAgo = secondsAgo;
			this.levels = levels;
			this.containers = containers;
		}

		public int[] items(String container)
		{
			return containers.getOrDefault(container, new int[0]);
		}

		public int level(String skill)
		{
			return levels.getOrDefault(skill, 1);
		}

		public int totalLevel()
		{
			int total = 0;
			for (int lvl : levels.values())
			{
				total += lvl;
			}
			return total;
		}

		public int combatLevel()
		{
			return Experience.getCombatLevel(level("attack"), level("strength"), level("defence"),
				Math.max(10, level("hitpoints")), level("magic"), level("ranged"), level("prayer"));
		}
	}

	private final ApiClient api;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final Map<Integer, String> names = new ConcurrentHashMap<>();
	private volatile List<Member> members = Collections.emptyList();
	@Getter
	private volatile long fetchedAtMillis;
	@Getter
	private volatile String groupName = "";
	private volatile int requestSeq;

	@Inject
	GroupData(ApiClient api, ClientThread clientThread, ItemManager itemManager)
	{
		this.api = api;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
	}

	public List<Member> getMembers()
	{
		return members;
	}

	/** Drop the cached snapshot, e.g. after leaving a group. */
	public void clear()
	{
		requestSeq++;
		members = Collections.emptyList();
		groupName = "";
		fetchedAtMillis = 0;
	}

	/** Item name from the game cache, or a placeholder until it has been resolved. */
	public String itemName(int itemId)
	{
		return names.getOrDefault(itemId, "Item " + itemId);
	}

	/**
	 * Fetch the group from the server. Both callbacks run on the Swing thread;
	 * onDone runs after every item name in the snapshot has been resolved.
	 */
	public void refresh(Runnable onDone, Consumer<String> onError)
	{
		int seq = ++requestSeq;
		api.get("/api/plugin/group", null, (json, error) ->
		{
			if (seq != requestSeq)
			{
				return; // a newer refresh (or a group switch) superseded this one
			}
			if (error != null)
			{
				SwingUtilities.invokeLater(() -> onError.accept(error));
				return;
			}
			List<Member> parsed;
			String name;
			try
			{
				parsed = parse(json);
				name = json.has("name") && json.get("name").isJsonPrimitive() ? json.get("name").getAsString() : "";
			}
			catch (RuntimeException e)
			{
				log.debug("Bad group data", e);
				SwingUtilities.invokeLater(() -> onError.accept("Could not read the group data"));
				return;
			}
			Runnable publish = () ->
			{
				if (seq != requestSeq)
				{
					return; // the user left or switched groups meanwhile
				}
				members = parsed;
				groupName = name;
				fetchedAtMillis = System.currentTimeMillis();
				onDone.run();
			};

			Set<Integer> missing = new HashSet<>();
			for (Member m : parsed)
			{
				for (String c : CONTAINERS)
				{
					int[] flat = m.items(c);
					for (int i = 0; i + 1 < flat.length; i += 2)
					{
						if (validItemId(flat[i]) && !names.containsKey(flat[i]) && missing.size() < MAX_LOOKUPS)
						{
							missing.add(flat[i]);
						}
					}
				}
			}
			if (missing.isEmpty())
			{
				SwingUtilities.invokeLater(publish);
				return;
			}
			// Item compositions may only be read on the client thread.
			clientThread.invokeLater(() ->
			{
				try
				{
					for (int id : missing)
					{
						// Ids come from other members' clients; one unknown id must not stop the rest.
						try
						{
							names.put(id, itemManager.getItemComposition(id).getName());
						}
						catch (RuntimeException e)
						{
							log.debug("Unknown item id {}", id, e);
						}
					}
				}
				finally
				{
					SwingUtilities.invokeLater(publish);
				}
			});
		});
	}

	private static List<Member> parse(JsonObject json)
	{
		List<Member> out = new ArrayList<>();
		if (json == null || !json.has("members") || !json.get("members").isJsonArray())
		{
			return out;
		}
		double now = number(json.get("now"), System.currentTimeMillis() / 1000.0);
		for (JsonElement el : json.getAsJsonArray("members"))
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject m = el.getAsJsonObject();
			if (!m.has("nick") || !m.get("nick").isJsonPrimitive())
			{
				continue;
			}
			JsonObject data = m.has("data") && m.get("data").isJsonObject() ? m.getAsJsonObject("data") : new JsonObject();

			Map<String, Integer> levels = new HashMap<>();
			if (data.has("levels") && data.get("levels").isJsonObject())
			{
				for (Map.Entry<String, JsonElement> e : data.getAsJsonObject("levels").entrySet())
				{
					levels.put(e.getKey(), (int) number(e.getValue(), 1));
				}
			}

			Map<String, int[]> containers = new HashMap<>();
			for (String c : CONTAINERS)
			{
				if (data.has(c) && data.get(c).isJsonArray())
				{
					JsonArray arr = data.getAsJsonArray(c);
					int[] flat = new int[arr.size()];
					for (int i = 0; i < flat.length; i++)
					{
						flat[i] = (int) number(arr.get(i), 0);
					}
					// [id, qty] pairs: an id outside the game's range blanks its whole slot.
					for (int i = 0; i + 1 < flat.length; i += 2)
					{
						if (!validItemId(flat[i]))
						{
							flat[i] = 0;
							flat[i + 1] = 0;
						}
					}
					containers.put(c, flat);
				}
			}

			double updatedAt = number(m.get("updated_at"), now);
			long ago = Math.max(0, Math.round(now - updatedAt));
			out.add(new Member(m.get("nick").getAsString(), ago, levels, containers));
		}
		return out;
	}

	private static boolean validItemId(int id)
	{
		return id >= 1 && id <= MAX_ITEM_ID;
	}

	/** A JSON number as a double, or {@code fallback} when it is missing or not numeric. */
	private static double number(JsonElement e, double fallback)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return fallback;
		}
		return e.getAsDouble();
	}
}

package fi.rosu.afkroulette;

import fi.rosu.afkroulette.sync.SyncManager;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Removes the player's shared data from a group on the server. The token is
 * passed explicitly because the configured one may already be gone (Leave group)
 * or belong to another group (token changed).
 */
@Slf4j
@Singleton
public class GroupLeaver
{
	private static final long REPEAT_WINDOW_MS = 5_000;

	private final ApiClient api;
	private final PlayerState player;
	private final SyncManager sync;
	/** Told when removing the data failed; runs on the HTTP thread. Set by the UI. */
	private volatile Consumer<String> failureListener;
	private String lastKey;
	private long lastAt;

	@Inject
	GroupLeaver(ApiClient api, PlayerState player, SyncManager sync)
	{
		this.api = api;
		this.player = player;
		this.sync = sync;
	}

	public void setFailureListener(Consumer<String> listener)
	{
		this.failureListener = listener;
	}

	/**
	 * Fire and forget. With {@code keepHistory} only the shared snapshot (levels, items...)
	 * goes and the player's tasks and streaks in the group stay (sharing turned off, token
	 * switched); without it the player leaves the group for good (Leave group). The Leave
	 * button and the config listener may both ask for the same leave, so a repeat within a
	 * few seconds is dropped.
	 */
	public void leave(String token, boolean keepHistory)
	{
		// The name the data was uploaded under, even if another character is logged in now.
		String name = sync.lastUploadedName() != null ? sync.lastUploadedName() : player.getName();
		if (token == null || token.trim().isEmpty())
		{
			return;
		}
		if (name == null)
		{
			notifyFailure("Log in to the game to remove your shared data from the group.");
			return;
		}
		String key = name + '\n' + token.trim() + '\n' + keepHistory;
		synchronized (this)
		{
			long now = System.currentTimeMillis();
			if (key.equals(lastKey) && now - lastAt < REPEAT_WINDOW_MS)
			{
				return;
			}
			lastKey = key;
			lastAt = now;
		}
		Map<String, Object> body = new HashMap<>();
		body.put("name", name);
		body.put("keep_history", keepHistory);
		// After any upload still on its way, so it can't put the data back.
		sync.runWhenIdle(() -> api.post("/api/plugin/group/leave", body, token.trim(), (json, error) ->
		{
			if (error == null)
			{
				return;
			}
			log.debug("Removing shared data from the group failed: {}", error);
			// The old token was reset on Discord: that group is gone for us anyway.
			if (!error.toLowerCase().contains("invalid group token"))
			{
				notifyFailure("Could not remove your shared data from the group (" + error + ").");
			}
		}));
	}

	private void notifyFailure(String message)
	{
		Consumer<String> listener = failureListener;
		if (listener != null)
		{
			listener.accept(message);
		}
	}
}

package fi.rosu.afkroulette;

import javax.inject.Singleton;

/**
 * The logged-in player's name, readable from any thread. Written on the client
 * thread by the plugin, read by the panel (EDT) and the uploader.
 */
@Singleton
public class PlayerState
{
	private volatile String name;

	public String getName()
	{
		return name;
	}

	void setName(String name)
	{
		this.name = name;
	}

	/** Game names can contain non-breaking spaces; the server expects plain ones. */
	static String normalize(String rawName)
	{
		return rawName == null ? null : rawName.replace(' ', ' ').trim();
	}
}

package fi.rosu.afkroulette.reel;

import fi.rosu.afkroulette.AfkRouletteConfig;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.SoundEffectID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A case-opening style reel drawn over the game view when a task is rolled:
 * icons slide past a marker, slow down and stop on the rolled task.
 */
@Singleton
public class RollOverlay extends Overlay
{
	/** How long the reel spins; the panel shows the task after this. */
	public static final long SPIN_MS = 5000;
	private static final long HOLD_MS = 3500;
	private static final long FADE_MS = 600;

	private static final int TILE = 52;
	private static final int GAP = 6;
	private static final int STEP = TILE + GAP;
	private static final int VISIBLE = 7;
	private static final int ICON = 40;
	/** Tiles in front of the start position, so the reel is full from the first frame. */
	private static final int LEAD = VISIBLE / 2 + 1;
	/** Index of the rolled task on the reel: enough tiles before it for a long spin. */
	private static final int WINNER_INDEX = LEAD + 30;
	private static final long TICK_SOUND_GAP_MS = 70;
	/** Drawn at up to twice the base size, shrunk to fit narrow (fixed mode) viewports. */
	private static final double MAX_SCALE = 2.0;
	private static final int VIEWPORT_MARGIN = 16;
	private static final int MAX_RESULT_CHARS = 100;
	private static final int MAX_ITEM_ID = 65535;

	private static final Color BACKGROUND = new Color(20, 18, 15, 225);
	private static final Color TILE_COLOR = new Color(58, 52, 44);
	private static final Color GOLD = new Color(245, 197, 66);

	private final Client client;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	private final AfkRouletteConfig config;

	/** Set from the Swing thread, cleared on the client thread when the reel has faded. */
	private final AtomicReference<Spin> spin = new AtomicReference<>();

	/** One reel icon: an item or a skill. */
	public static final class Icon
	{
		final int item;
		final String skill;

		private Icon(int item, String skill)
		{
			this.item = item;
			this.skill = skill;
		}

		public static Icon item(int id)
		{
			return new Icon(id, null);
		}

		public static Icon skill(String name)
		{
			return new Icon(0, name);
		}
	}

	private static final class Spin
	{
		final List<Icon> tiles;
		final String heading;
		final String result;
		final long start;
		/** Where the marker stops inside the winning tile, so it doesn't always land dead centre. */
		final int stopOffset;
		final Map<Icon, BufferedImage> images = new HashMap<>();
		int lastTile = -1;
		long lastSound;
		boolean winSoundPlayed;

		Spin(List<Icon> tiles, String heading, String result)
		{
			this.tiles = tiles;
			this.heading = heading;
			this.result = result;
			this.start = System.currentTimeMillis();
			this.stopOffset = ThreadLocalRandom.current().nextInt(-TILE / 3, TILE / 3 + 1);
		}
	}

	@Inject
	RollOverlay(Client client, ItemManager itemManager, SkillIconManager skillIconManager, AfkRouletteConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	/**
	 * Spin the reel and stop on {@code winner}. Returns how long to wait before
	 * showing the result, or 0 when the reel is off or there is nothing to spin.
	 */
	public long play(List<Icon> reel, Icon winner, String heading, String result)
	{
		if (!config.rollAnimation() || !valid(winner))
		{
			return 0;
		}
		// The reel comes from the server: only icons the game can actually have are drawn.
		List<Icon> usable = new ArrayList<>();
		for (Icon icon : reel)
		{
			if (valid(icon))
			{
				usable.add(icon);
			}
		}
		if (usable.isEmpty())
		{
			return 0;
		}
		List<Icon> tiles = new ArrayList<>();
		for (int i = 0; i < WINNER_INDEX + VISIBLE; i++)
		{
			tiles.add(i == WINNER_INDEX ? winner : usable.get(i % usable.size()));
		}
		String text = result == null ? "" : result.length() > MAX_RESULT_CHARS ? result.substring(0, MAX_RESULT_CHARS) : result;
		spin.set(new Spin(tiles, heading, text));
		return SPIN_MS;
	}

	private static boolean valid(Icon icon)
	{
		return icon != null && (icon.skill != null || (icon.item >= 1 && icon.item <= MAX_ITEM_ID));
	}

	public void stop()
	{
		spin.set(null);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Spin s = spin.get();
		if (s == null)
		{
			return null;
		}
		long t = System.currentTimeMillis() - s.start;
		if (t > SPIN_MS + HOLD_MS + FADE_MS)
		{
			// A reel started meanwhile must not be cleared.
			spin.compareAndSet(s, null);
			return null;
		}

		double p = Math.min(1.0, t / (double) SPIN_MS);
		double eased = 1 - Math.pow(1 - p, 4);
		double startPos = LEAD * STEP;
		double distance = (WINNER_INDEX - LEAD) * STEP + s.stopOffset;
		double pos = startPos + distance * eased;
		boolean stopped = p >= 1.0;
		playSounds(s, pos, stopped);

		Composite oldComposite = g.getComposite();
		long fadeAt = SPIN_MS + HOLD_MS;
		if (t > fadeAt)
		{
			float alpha = Math.max(0f, 1f - (t - fadeAt) / (float) FADE_MS);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		int width = VISIBLE * STEP + GAP;
		int height = TILE + 70;
		double scale = Math.max(0.5, Math.min(MAX_SCALE,
			(client.getViewportWidth() - 2 * VIEWPORT_MARGIN) / (double) width));
		double screenX = client.getViewportXOffset() + (client.getViewportWidth() - width * scale) / 2;
		double screenY = Math.max(client.getViewportYOffset() + VIEWPORT_MARGIN,
			client.getViewportYOffset() + client.getViewportHeight() / 4.0 - height * scale / 2);
		AffineTransform oldTransform = g.getTransform();
		g.translate(screenX, screenY);
		g.scale(scale, scale);
		// From here on everything is drawn at base size with the box's top-left at (0, 0).
		int centerX = width / 2;
		int x = 0;
		int y = 0;

		g.setColor(BACKGROUND);
		g.fillRoundRect(x, y, width, height, 10, 10);
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(2));
		g.drawRoundRect(x, y, width, height, 10, 10);

		g.setFont(FontManager.getRunescapeBoldFont());
		drawCentered(g, s.heading, centerX, y + 18, GOLD);

		int stripY = y + 26;
		Shape oldClip = g.getClip();
		g.clipRect(x + 2, stripY, width - 4, TILE);
		int first = Math.max(0, (int) Math.floor((pos - width / 2.0) / STEP) - 1);
		int last = Math.min(s.tiles.size() - 1, (int) Math.ceil((pos + width / 2.0) / STEP) + 1);
		for (int i = first; i <= last; i++)
		{
			int tileX = (int) Math.round(centerX + i * STEP - pos - TILE / 2.0);
			boolean winner = stopped && i == WINNER_INDEX;
			g.setColor(winner ? GOLD.darker() : TILE_COLOR);
			g.fillRect(tileX, stripY, TILE, TILE);
			if (winner)
			{
				g.setColor(GOLD);
				g.drawRect(tileX, stripY, TILE - 1, TILE - 1);
			}
			BufferedImage img = image(s, s.tiles.get(i));
			if (img != null)
			{
				double fitIcon = Math.min(ICON / (double) img.getWidth(), ICON / (double) img.getHeight());
				int w = (int) Math.round(img.getWidth() * fitIcon);
				int h = (int) Math.round(img.getHeight() * fitIcon);
				g.drawImage(img, tileX + (TILE - w) / 2, stripY + (TILE - h) / 2, w, h, null);
			}
		}
		g.setClip(oldClip);

		// The marker the reel stops under.
		g.setColor(GOLD);
		g.fillPolygon(new int[]{centerX - 7, centerX + 7, centerX}, new int[]{stripY - 6, stripY - 6, stripY + 4}, 3);
		g.fillPolygon(new int[]{centerX - 7, centerX + 7, centerX}, new int[]{stripY + TILE + 6, stripY + TILE + 6, stripY + TILE - 4}, 3);
		g.drawLine(centerX, stripY, centerX, stripY + TILE);

		if (stopped)
		{
			g.setFont(FontManager.getRunescapeBoldFont());
			drawCentered(g, fit(g, s.result, width - 16), centerX, stripY + TILE + 24, Color.WHITE);
		}
		g.setTransform(oldTransform);
		g.setComposite(oldComposite);
		return null;
	}

	private void playSounds(Spin s, double pos, boolean stopped)
	{
		// playSoundEffect(id) would play even with game sounds muted; follow the player's volume.
		int volume = client.getPreferences().getSoundEffectVolume();
		if (!config.rollSound() || volume <= 0)
		{
			return;
		}
		int tile = (int) Math.floor((pos + STEP / 2.0) / STEP);
		long now = System.currentTimeMillis();
		if (!stopped && tile != s.lastTile && now - s.lastSound >= TICK_SOUND_GAP_MS)
		{
			client.playSoundEffect(SoundEffectID.UI_BOOP, volume);
			s.lastSound = now;
		}
		s.lastTile = tile;
		if (stopped && !s.winSoundPlayed)
		{
			s.winSoundPlayed = true;
			client.playSoundEffect(SoundEffectID.GE_ADD_OFFER_DINGALING, volume);
		}
	}

	private BufferedImage image(Spin s, Icon icon)
	{
		if (s.images.containsKey(icon))
		{
			return s.images.get(icon);
		}
		BufferedImage img = null;
		if (icon.skill != null)
		{
			Skill skill = skill(icon.skill);
			if (skill != null)
			{
				img = skillIconManager.getSkillImage(skill);
			}
		}
		else if (icon.item > 0)
		{
			img = itemManager.getImage(icon.item);
		}
		s.images.put(icon, img);
		return img;
	}

	private static Skill skill(String name)
	{
		String wanted = "combat".equalsIgnoreCase(name) ? "attack" : name;
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(wanted))
			{
				return skill;
			}
		}
		return null;
	}

	private static void drawCentered(Graphics2D g, String text, int centerX, int baseline, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		int x = centerX - fm.stringWidth(text) / 2;
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(text, x, baseline);
	}

	private static String fit(Graphics2D g, String text, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics();
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String cut = text;
		while (cut.length() > 1 && fm.stringWidth(cut + "...") > maxWidth)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + "...";
	}
}

package fi.rosu.afkroulette.sync;

import fi.rosu.afkroulette.AfkRouletteConfig;
import fi.rosu.afkroulette.ApiClient;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Uploads the player's data to the group, sending only the parts that changed
 * since the last successful upload and re-queueing them if an upload fails.
 *
 * The idea of uploading only changed data is the same one Group Ironmen Tracker
 * (https://github.com/christoabrown/group-ironmen-tracker) uses; this is our own
 * implementation.
 */
@Slf4j
@Singleton
public class SyncManager
{
	/** Failed uploads pause the uploader for this many submit rounds. */
	private static final int BACKOFF_ROUNDS = 15;

	private static final class Entry
	{
		String owner;
		Object last;
		Object pending;
	}

	private final Map<String, Entry> entries = new HashMap<>();
	private final ApiClient api;
	private final AfkRouletteConfig config;
	private boolean inFlight;
	private int skipRounds;
	/** The name the last successful upload went out under (the group knows the data by it). */
	private volatile String lastUploadedName;
	/** Work that must wait for the upload in flight, e.g. removing the data from the group. */
	private final List<Runnable> whenIdle = new ArrayList<>();

	@Inject
	SyncManager(ApiClient api, AfkRouletteConfig config)
	{
		this.api = api;
		this.config = config;
	}

	/**
	 * Record the latest value for a field. Values are plain collections, so
	 * equals() tells whether anything actually changed.
	 */
	public synchronized void update(String owner, String key, Object value)
	{
		if (owner == null || value == null)
		{
			return;
		}
		Entry e = entries.computeIfAbsent(key, k -> new Entry());
		if (!owner.equals(e.owner) || !Objects.equals(value, e.last))
		{
			e.owner = owner;
			e.last = value;
			e.pending = value;
		}
	}

	/** Upload pending changes. Called off the client thread. */
	public void submit(String playerName)
	{
		if (playerName == null || !config.serverEnabled() || !config.shareData()
			|| config.groupToken().trim().isEmpty())
		{
			return;
		}

		Map<String, Object> body = new HashMap<>();
		List<String> taken = new ArrayList<>();
		synchronized (this)
		{
			if (inFlight)
			{
				return;
			}
			if (skipRounds > 0)
			{
				skipRounds--;
				return;
			}
			for (Map.Entry<String, Entry> en : entries.entrySet())
			{
				Entry e = en.getValue();
				// Data captured on another character (account switch) is never sent under this name.
				if (e.pending != null && playerName.equals(e.owner))
				{
					body.put(en.getKey(), e.pending);
					e.pending = null;
					taken.add(en.getKey());
				}
			}
			if (taken.isEmpty())
			{
				return;
			}
			inFlight = true;
		}

		body.put("name", playerName);
		try
		{
			api.post("/api/plugin/update", body, (json, error) -> finish(taken, playerName, error));
		}
		catch (RuntimeException e)
		{
			// The request never left: without this the uploader would stay "in flight" forever.
			finish(taken, playerName, "Request could not be sent");
		}
	}

	/** Ends an upload round; on failure the taken fields are queued again. */
	private void finish(List<String> taken, String playerName, String error)
	{
		List<Runnable> run;
		synchronized (this)
		{
			inFlight = false;
			if (error == null)
			{
				lastUploadedName = playerName;
			}
			else
			{
				log.debug("Group sync failed: {}", error);
				skipRounds = BACKOFF_ROUNDS;
				for (String key : taken)
				{
					Entry e = entries.get(key);
					if (e != null && e.pending == null && playerName.equals(e.owner))
					{
						e.pending = e.last;
					}
				}
			}
			run = new ArrayList<>(whenIdle);
			whenIdle.clear();
		}
		run.forEach(Runnable::run);
	}

	/** Runs {@code task} now, or once the upload in flight has finished. */
	public void runWhenIdle(Runnable task)
	{
		synchronized (this)
		{
			if (inFlight)
			{
				whenIdle.add(task);
				return;
			}
		}
		task.run();
	}

	public String lastUploadedName()
	{
		return lastUploadedName;
	}

	/** Send everything again, e.g. after the token or the share toggle changes. */
	public synchronized void resendAll()
	{
		for (Entry e : entries.values())
		{
			e.pending = e.last;
		}
		skipRounds = 0;
	}

	public void reset()
	{
		List<Runnable> run;
		synchronized (this)
		{
			entries.clear();
			inFlight = false;
			skipRounds = 0;
			run = new ArrayList<>(whenIdle);
			whenIdle.clear();
		}
		run.forEach(Runnable::run);
	}
}

