/**
 * Create / join / leave a group, then see the members' levels, worn gear and
 * inventory. Each group is its own token-protected space on the server.
 */
@Singleton
public class GroupTab extends JPanel
{
	private static final String TOKEN_KEY = "groupToken";

	/** Same order as the in-game skills tab. */
	private static final Skill[] SKILL_ORDER = {
		Skill.ATTACK, Skill.HITPOINTS, Skill.MINING,
		Skill.STRENGTH, Skill.AGILITY, Skill.SMITHING,
		Skill.DEFENCE, Skill.HERBLORE, Skill.FISHING,
		Skill.RANGED, Skill.THIEVING, Skill.COOKING,
		Skill.PRAYER, Skill.CRAFTING, Skill.FIREMAKING,
		Skill.MAGIC, Skill.FLETCHING, Skill.WOODCUTTING,
		Skill.RUNECRAFT, Skill.SLAYER, Skill.FARMING,
		Skill.CONSTRUCTION, Skill.HUNTER, Skill.SAILING,
	};
	private static final long STALE_MILLIS = 60_000;
	private static final int SCORE_ROWS = 5;

	private final GroupData group;
	private final ItemManager itemManager;
	private final SkillIconManager skillIcons;
	private final AfkRouletteConfig config;
	private final ConfigManager configManager;
	private final ApiClient api;
	private final GroupLeaver leaver;
	private final JPanel groupBox = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
	private final JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JPanel scores = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
	private final JLabel status = Ui.label("", Ui.MUTED, false);
	private final JButton refresh = Ui.button("Refresh");
	private final Set<String> expanded = new HashSet<>();

	@Inject
	GroupTab(GroupData group, ItemManager itemManager, SkillIconManager skillIcons, AfkRouletteConfig config,
		ConfigManager configManager, ApiClient api, GroupLeaver leaver)
	{
		this.group = group;
		this.itemManager = itemManager;
		this.skillIcons = skillIcons;
		this.config = config;
		this.configManager = configManager;
		this.api = api;
		this.leaver = leaver;
		leaver.setFailureListener(error -> SwingUtilities.invokeLater(() ->
		{
			status.setForeground(Ui.ERROR);
			status.setText(Ui.wrap(error));
		}));

		setLayout(new DynamicGridLayout(0, 1, 0, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		groupBox.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		groupBox.setBorder(new EmptyBorder(8, 8, 8, 8));
		list.setOpaque(false);
		refresh.addActionListener(e -> refresh());
		add(groupBox);
		add(refresh);
		add(status);
		add(list);
		scores.setOpaque(false);
		add(scores);
		rebuildGroupBox();
	}

	public void refreshIfStale()
	{
		if (System.currentTimeMillis() - group.getFetchedAtMillis() > STALE_MILLIS)
		{
			refresh();
		}
	}

	public void refresh()
	{
		rebuildGroupBox();
		if (!inGroup())
		{
			group.clear();
			list.removeAll();
			list.revalidate();
			list.repaint();
			scores.removeAll();
			scores.revalidate();
			scores.repaint();
			refresh.setVisible(false);
			setStatus("");
			return;
		}
		refresh.setVisible(true);
		refresh.setEnabled(false);
		setStatus("Loading...");
		loadScores();
		group.refresh(() ->
		{
			refresh.setEnabled(true);
			if (!inGroup())
			{
				return;
			}
			rebuildGroupBox();
			render();
		}, error ->
		{
			refresh.setEnabled(true);
			status.setForeground(Ui.ERROR);
			status.setText(Ui.wrap(error));
		});
	}

	private boolean inGroup()
	{
		return config.serverEnabled() && !config.groupToken().trim().isEmpty();
	}

	/** The create / join / leave controls on top of the tab. */
	private void rebuildGroupBox()
	{
		groupBox.removeAll();
		if (!config.serverEnabled())
		{
			groupBox.add(Ui.label("Turn on \"Connect to AFK Roulette server\" in the plugin settings "
				+ "to create or join a group.", Ui.MUTED, false, Ui.TEXT_WIDTH - 16));
		}
		else if (config.groupToken().trim().isEmpty())
		{
			buildCreateJoin();
		}
		else
		{
			String name = group.getGroupName();
			groupBox.add(Ui.label("Group: " + (name == null || name.isEmpty() ? "connected" : name),
				Ui.GOLD, true, Ui.TEXT_WIDTH - 16));
			groupBox.add(Ui.label("Share the token with your group so they can join. "
				+ "Only people with the token can see the group's data.", Ui.MUTED, false, Ui.TEXT_WIDTH - 16));
			JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
			row.setOpaque(false);
			JButton copy = Ui.button("Copy token");
			copy.addActionListener(e ->
			{
				Toolkit.getDefaultToolkit().getSystemClipboard()
					.setContents(new StringSelection(config.groupToken().trim()), null);
				copy.setText("Copied!");
			});
			JButton leave = Ui.button("Leave group");
			leave.addActionListener(e -> leaveGroup());
			row.add(copy);
			row.add(leave);
			groupBox.add(row);
		}
		groupBox.revalidate();
		groupBox.repaint();
	}

	private void buildCreateJoin()
	{
		int width = Ui.TEXT_WIDTH - 16;
		groupBox.add(Ui.label("You're not in a group yet.", Ui.GOLD, true, width));

		groupBox.add(Ui.label("Create a new group:", Ui.MUTED, false, width));
		JTextField nameField = field("Group name");
		JButton create = Ui.button("Create group");
		groupBox.add(nameField);
		groupBox.add(create);

		groupBox.add(Ui.label("Or join with a token from your group:", Ui.MUTED, false, width));
		JTextField tokenField = field("Group token");
		JButton join = Ui.button("Join group");
		groupBox.add(tokenField);
		groupBox.add(join);

		JLabel feedback = Ui.label("", Ui.MUTED, false, width);
		groupBox.add(feedback);

		create.addActionListener(e ->
		{
			String name = nameField.getText().trim();
			if (name.isEmpty())
			{
				showFeedback(feedback, "Give the group a name.", Ui.ERROR);
				return;
			}
			create.setEnabled(false);
			Map<String, Object> body = new HashMap<>();
			body.put("name", name);
			api.post("/api/plugin/group/create", body, (json, error) -> SwingUtilities.invokeLater(() ->
			{
				create.setEnabled(true);
				if (error != null)
				{
					showFeedback(feedback, error, Ui.ERROR);
					return;
				}
				String token = str(json, "token");
				if (token == null || !ApiClient.isValidToken(token))
				{
					showFeedback(feedback, "The server sent an unexpected reply. Try again.", Ui.ERROR);
					return;
				}
				// Saving the token fires ConfigChanged, which refreshes this tab.
				configManager.setConfiguration(AfkRouletteConfig.GROUP, TOKEN_KEY, token);
			}));
		});

		join.addActionListener(e ->
		{
			// Pasted tokens often carry spaces, line breaks or zero-width characters.
			String token = cleanToken(tokenField.getText());
			if (token.isEmpty())
			{
				showFeedback(feedback, "Paste the token you got from your group.", Ui.ERROR);
				return;
			}
			if (!ApiClient.isValidToken(token))
			{
				showFeedback(feedback, "That doesn't look like a group token. Copy it again from your group.", Ui.ERROR);
				return;
			}
			join.setEnabled(false);
			api.get("/api/plugin/group/info", null, token, (json, error) -> SwingUtilities.invokeLater(() ->
			{
				join.setEnabled(true);
				if (error != null)
				{
					showFeedback(feedback, "That token didn't work: " + error, Ui.ERROR);
					return;
				}
				configManager.setConfiguration(AfkRouletteConfig.GROUP, TOKEN_KEY, token);
			}));
		});
	}

	private void leaveGroup()
	{
		int answer = JOptionPane.showConfirmDialog(this,
			"Leave the group? Your shared data is removed from it.\nYou can join again with the token.",
			"Leave group", JOptionPane.YES_NO_OPTION);
		if (answer != JOptionPane.YES_OPTION)
		{
			return;
		}
		String token = config.groupToken().trim();
		// Forget the token first so the uploader stops, then delete our data with it.
		configManager.unsetConfiguration(AfkRouletteConfig.GROUP, TOKEN_KEY);
		leaver.leave(token, false);
	}

	/** Strips whitespace (incl. non-breaking) and zero-width characters from a pasted token. */
	private static String cleanToken(String raw)
	{
		return raw == null ? "" : raw.trim().replaceAll("[\\s\\u00A0\\u200B-\\u200F\\u2060\\uFEFF]", "");
	}

	private static String str(JsonObject o, String key)
	{
		if (o == null || !o.has(key) || !o.get(key).isJsonPrimitive())
		{
			return null;
		}
		return o.get(key).getAsString();
	}

	private static String nz(String s)
	{
		return s == null ? "" : s;
	}

	private static int integer(JsonObject o, String key)
	{
		if (o == null || !o.has(key) || !o.get(key).isJsonPrimitive())
		{
			return 0;
		}
		try
		{
			return o.get(key).getAsInt();
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** The array under {@code key}, or an empty one when it is missing or of the wrong type. */
	private static JsonArray array(JsonObject o, String key)
	{
		return o != null && o.has(key) && o.get(key).isJsonArray() ? o.getAsJsonArray(key) : new JsonArray();
	}

	private static JTextField field(String tooltip)
	{
		JTextField f = new JTextField();
		f.setToolTipText(tooltip);
		f.setBackground(ColorScheme.DARK_GRAY_COLOR);
		f.setForeground(Color.WHITE);
		f.setCaretColor(Color.WHITE);
		f.setBorder(new EmptyBorder(6, 6, 6, 6));
		f.setPreferredSize(new Dimension(0, 28));
		return f;
	}

	private static void showFeedback(JLabel label, String text, Color color)
	{
		label.setForeground(color);
		label.setText(Ui.wrap(text, Ui.TEXT_WIDTH - 16));
	}

	/** The group's own highscores (the server scopes them by the group token). */
	private void loadScores()
	{
		api.get("/api/leaderboard", null, (afk, afkError) ->
			api.get("/api/tasker/highscores", null, (tasker, taskerError) -> SwingUtilities.invokeLater(() ->
			{
				scores.removeAll();
				if (afkError == null && taskerError == null && inGroup())
				{
					scores.add(Ui.label("Group highscores", Ui.GOLD, true));
					addAfkScores(afk);
					addTaskerScores(tasker, "task", "Task");
					addTaskerScores(tasker, "boss", "Boss");
					addTaskerScores(tasker, "collection", "Collection log");
				}
				scores.revalidate();
				scores.repaint();
			})));
	}

	private void addAfkScores(JsonObject json)
	{
		JsonArray players = array(json, "players");
		if (players.size() == 0)
		{
			return;
		}
		scores.add(Ui.label("AFK (daily)", Ui.MUTED, true));
		int rank = 1;
		for (JsonElement el : players)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject p = el.getAsJsonObject();
			scores.add(Ui.label(rank + ". " + nz(str(p, "nick")) + " — streak " + integer(p, "current")
				+ " · done " + integer(p, "done") + " · skips " + integer(p, "skips"),
				ColorScheme.LIGHT_GRAY_COLOR, false));
			if (++rank > SCORE_ROWS)
			{
				break;
			}
		}
	}

	private void addTaskerScores(JsonObject json, String key, String title)
	{
		JsonArray entries = array(json, key);
		if (entries.size() == 0)
		{
			return;
		}
		scores.add(Ui.label(title, Ui.MUTED, true));
		int rank = 1;
		for (JsonElement el : entries)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject p = el.getAsJsonObject();
			scores.add(Ui.label(rank + ". " + nz(str(p, "nick")) + " — done " + integer(p, "done")
				+ " · skips " + integer(p, "skips"), ColorScheme.LIGHT_GRAY_COLOR, false));
			if (++rank > SCORE_ROWS)
			{
				break;
			}
		}
	}

	private void render()
	{
		List<GroupData.Member> members = group.getMembers();
		list.removeAll();
		if (members.isEmpty())
		{
			setStatus("Nobody has shared data yet. Turn on \"Share my data\" in the plugin settings.");
		}
		else
		{
			setStatus(members.size() + " member(s). Click a name to show details.");
			for (GroupData.Member m : members)
			{
				list.add(memberCard(m));
			}
		}
		list.revalidate();
		list.repaint();
	}

	private JPanel memberCard(GroupData.Member m)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel header = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		header.setOpaque(false);
		header.add(Ui.label(m.getNick(), Ui.GOLD, true));
		header.add(Ui.label("Combat " + m.combatLevel() + " · Total " + m.totalLevel()
			+ " · " + Ui.ago(m.getSecondsAgo()), Ui.MUTED, false));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		card.add(header, BorderLayout.NORTH);

		JPanel details = details(m);
		details.setVisible(expanded.contains(m.getNick()));
		card.add(details, BorderLayout.CENTER);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				boolean show = !details.isVisible();
				details.setVisible(show);
				if (show)
				{
					expanded.add(m.getNick());
				}
				else
				{
					expanded.remove(m.getNick());
				}
				card.revalidate();
			}
		});
		return card;
	}

	private JPanel details(GroupData.Member m)
	{
		JPanel d = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		d.setOpaque(false);
		d.setBorder(new EmptyBorder(8, 0, 0, 0));

		JPanel skills = new JPanel(new GridLayout(0, 3, 2, 2));
		skills.setOpaque(false);
		for (Skill skill : SKILL_ORDER)
		{
			JLabel l = new JLabel(String.valueOf(m.level(skill.getName().toLowerCase())));
			l.setIcon(new ImageIcon(skillIcons.getSkillImage(skill, true)));
			l.setForeground(Ui.GOLD);
			l.setToolTipText(skill.getName());
			skills.add(l);
		}
		d.add(skills);

		int[] worn = m.items("equipment");
		if (hasItems(worn))
		{
			d.add(Ui.label("Equipment", Ui.MUTED, false));
			JPanel gear = new JPanel(new GridLayout(0, 4, 2, 2));
			gear.setOpaque(false);
			addItems(gear, worn, false);
			d.add(gear);
		}

		int[] inv = m.items("inventory");
		if (hasItems(inv))
		{
			d.add(Ui.label("Inventory", Ui.MUTED, false));
			JPanel grid = new JPanel(new GridLayout(0, 4, 2, 2));
			grid.setOpaque(false);
			addItems(grid, inv, true);
			d.add(grid);
		}
		return d;
	}

	private void addItems(JPanel target, int[] flat, boolean keepEmptySlots)
	{
		for (int i = 0; i + 1 < flat.length; i += 2)
		{
			int id = flat[i];
			int qty = flat[i + 1];
			if (id <= 0 || qty <= 0)
			{
				if (keepEmptySlots)
				{
					target.add(emptySlot());
				}
				continue;
			}
			target.add(itemIcon(id, qty));
		}
	}

	private JLabel itemIcon(int id, int qty)
	{
		JLabel l = new JLabel();
		l.setPreferredSize(new Dimension(36, 32));
		AsyncBufferedImage img = itemManager.getImage(id, qty, qty > 1);
		img.addTo(l);
		l.setToolTipText(group.itemName(id) + (qty > 1 ? String.format(" x %,d", qty) : ""));
		return l;
	}

	private static JLabel emptySlot()
	{
		JLabel l = new JLabel();
		l.setPreferredSize(new Dimension(36, 32));
		return l;
	}

	private static boolean hasItems(int[] flat)
	{
		for (int i = 0; i + 1 < flat.length; i += 2)
		{
			if (flat[i] > 0 && flat[i + 1] > 0)
			{
				return true;
			}
		}
		return false;
	}

	private void setStatus(String text)
	{
		status.setForeground(Ui.MUTED);
		status.setText(Ui.wrap(text));
	}
}

package fi.rosu.afkroulette.ui;

import fi.rosu.afkroulette.GroupData;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.components.IconTextField;

/**
 * Search every group member's bank, inventory, worn gear and seed vault at once,
 * e.g. "lobster" lists Lobster and Raw lobster separately per member.
 */
@Singleton
public class ItemsTab extends JPanel
{
	private static final int MAX_RESULTS = 40;
	/** Card text sits next to a 36 px item icon. */
	private static final int CARD_TEXT_WIDTH = Ui.TEXT_WIDTH - 54;
	private static final long STALE_MILLIS = 60_000;
	private static final Map<String, String> CONTAINER_NAMES = new LinkedHashMap<>();

	static
	{
		CONTAINER_NAMES.put("bank", "bank");
		CONTAINER_NAMES.put("inventory", "inv");
		CONTAINER_NAMES.put("equipment", "worn");
		CONTAINER_NAMES.put("seed_vault", "seed vault");
	}

	private final GroupData group;
	private final ItemManager itemManager;
	private final IconTextField search = new IconTextField();
	private final JLabel status = Ui.label("", Ui.MUTED, false);
	private final JPanel results = new JPanel(new DynamicGridLayout(0, 1, 0, 6));

	@Inject
	ItemsTab(GroupData group, ItemManager itemManager)
	{
		this.group = group;
		this.itemManager = itemManager;

		setLayout(new DynamicGridLayout(0, 1, 0, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 30));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				render();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				render();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				render();
			}
		});
		results.setOpaque(false);

		add(search);
		add(status);
		add(results);
		render();
	}

	public void onShown()
	{
		if (System.currentTimeMillis() - group.getFetchedAtMillis() > STALE_MILLIS)
		{
			status.setForeground(Ui.MUTED);
			status.setText(Ui.wrap("Loading the group's items..."));
			group.refresh(this::render, error ->
			{
				status.setForeground(Ui.ERROR);
				status.setText(Ui.wrap(error));
			});
		}
	}

	private void render()
	{
		results.removeAll();
		String query = search.getText().trim().toLowerCase();
		if (query.length() < 2)
		{
			setStatus("Search the whole group's banks, inventories and gear, e.g. \"lobster\".");
			refreshResults();
			return;
		}

		// item id -> member -> container -> quantity
		Map<Integer, Map<String, Map<String, Long>>> hits = new TreeMap<>();
		for (GroupData.Member m : group.getMembers())
		{
			for (String container : CONTAINER_NAMES.keySet())
			{
				int[] flat = m.items(container);
				for (int i = 0; i + 1 < flat.length; i += 2)
				{
					int id = flat[i];
					int qty = flat[i + 1];
					if (id <= 0 || qty <= 0 || !group.itemName(id).toLowerCase().contains(query))
					{
						continue;
					}
					hits.computeIfAbsent(id, k -> new LinkedHashMap<>())
						.computeIfAbsent(m.getNick(), k -> new LinkedHashMap<>())
						.merge(container, (long) qty, Long::sum);
				}
			}
		}

		if (hits.isEmpty())
		{
			setStatus(group.getMembers().isEmpty()
				? "No group data yet. Make sure the server options are on in the plugin settings."
				: "Nobody in the group has \"" + query + "\".");
			refreshResults();
			return;
		}

		List<Map.Entry<Integer, Map<String, Map<String, Long>>>> sorted = new ArrayList<>(hits.entrySet());
		sorted.sort((a, b) -> Long.compare(total(b.getValue()), total(a.getValue())));
		setStatus(sorted.size() > MAX_RESULTS
			? "Showing the " + MAX_RESULTS + " most common of " + sorted.size() + " matches."
			: sorted.size() + " matching item(s).");
		for (Map.Entry<Integer, Map<String, Map<String, Long>>> e : sorted.subList(0, Math.min(MAX_RESULTS, sorted.size())))
		{
			results.add(itemCard(e.getKey(), e.getValue()));
		}
		refreshResults();
	}

	private JPanel itemCard(int itemId, Map<String, Map<String, Long>> byMember)
	{
		JPanel card = new JPanel(new BorderLayout(6, 0));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(6, 6, 6, 6));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		itemManager.getImage(itemId).addTo(icon);
		card.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		text.setOpaque(false);
		text.add(Ui.label(group.itemName(itemId) + String.format(" — %,d", total(byMember)), Ui.GOLD, true, CARD_TEXT_WIDTH));
		for (Map.Entry<String, Map<String, Long>> m : byMember.entrySet())
		{
			List<String> parts = new ArrayList<>();
			for (Map.Entry<String, Long> c : m.getValue().entrySet())
			{
				parts.add(CONTAINER_NAMES.get(c.getKey()) + String.format(" %,d", c.getValue()));
			}
			long sum = m.getValue().values().stream().mapToLong(Long::longValue).sum();
			text.add(Ui.label(m.getKey() + String.format(": %,d", sum) + " (" + String.join(", ", parts) + ")",
				ColorScheme.LIGHT_GRAY_COLOR, false, CARD_TEXT_WIDTH));
		}
		card.add(text, BorderLayout.CENTER);
		return card;
	}

	private static long total(Map<String, Map<String, Long>> byMember)
	{
		long sum = 0;
		for (Map<String, Long> containers : byMember.values())
		{
			for (long q : containers.values())
			{
				sum += q;
			}
		}
		return sum;
	}

	private void setStatus(String text)
	{
		status.setForeground(Ui.MUTED);
		status.setText(Ui.wrap(text));
	}

	private void refreshResults()
	{
		results.revalidate();
		results.repaint();
	}
}

package fi.rosu.afkroulette.ui;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import fi.rosu.afkroulette.ApiClient;
import fi.rosu.afkroulette.PlayerState;
import fi.rosu.afkroulette.reel.RollOverlay;
import fi.rosu.afkroulette.tracker.TaskTracker;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.util.LinkBrowser;
import okhttp3.HttpUrl;

/**
 * Roll / Done / Skip for AFK tasks and the Task, Boss and Collection
 * log generators. Uses the same server endpoints as the website and Discord,
 * so tasks, streaks and highscores are shared everywhere.
 */
@Singleton
public class TasksTab extends JPanel
{
	private static final String WIKI_HOST = "oldschool.runescape.wiki";
	private static final String WIKI = "https://" + WIKI_HOST;
	private static final String QUEST_PREFIX = "Complete the quest: ";

	private enum Category
	{
		AFK("AFK", "afk", "Daily AFK task"),
		TASK("Task", "task", "Skill task"),
		BOSS("Boss", "boss", "Boss task"),
		COLLECTION("Clog", "collection", "Collection log task");

		final String label;
		final String key;
		final String heading;

		Category(String label, String key, String heading)
		{
			this.label = label;
			this.key = key;
			this.heading = heading;
		}
	}

	private final ApiClient api;
	private final PlayerState player;
	private final TaskTracker tracker;
	private final RollOverlay rollOverlay;
	private final Map<Category, JButton> categoryButtons = new EnumMap<>(Category.class);
	private final JLabel title = Ui.label("", Ui.GOLD, true);
	private final JLabel meta = Ui.label("", Ui.MUTED, false);
	private final JLabel tip = Ui.label("", Ui.MUTED, false);
	private final JLabel progress = Ui.label("", Ui.OK, false);
	private final JLabel status = Ui.label("", Ui.MUTED, false);
	private final JButton roll = Ui.button("Roll");
	private final JButton done = Ui.button("Done");
	private final JButton skip = Ui.button("Skip");
	private final JButton already = Ui.button("Already done");

	private Category category = Category.AFK;
	private String wikiUrl;
	private boolean hasTask;
	private boolean taskIsDone;
	private boolean taskIsQuest;
	private boolean busy;
	/** Status to show after the next card reload (e.g. after an automatic completion). */
	private String pendingStatus;
	/** Name of the task on the card, sent with Done/Skip so a stale card can't finish another task. */
	private String shownTaskName;
	/** Bumped when the view changes, so a reel finishing late doesn't show a stale result. */
	private int generation;

	@Inject
	TasksTab(ApiClient api, PlayerState player, TaskTracker tracker, RollOverlay rollOverlay)
	{
		this.api = api;
		this.player = player;
		this.tracker = tracker;
		this.rollOverlay = rollOverlay;
		tracker.addListener((cat, completed) -> SwingUtilities.invokeLater(() -> onTracker(cat, completed)));

		setLayout(new DynamicGridLayout(0, 1, 0, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel categories = new JPanel(new GridLayout(1, 4, 4, 0));
		categories.setOpaque(false);
		for (Category c : Category.values())
		{
			JButton b = Ui.button(c.label);
			b.addActionListener(e -> select(c));
			categoryButtons.put(c, b);
			categories.add(b);
		}
		add(categories);

		JPanel card = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(10, 10, 10, 10));
		title.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (wikiUrl != null)
				{
					LinkBrowser.browse(wikiUrl);
				}
			}
		});
		card.add(title);
		card.add(meta);
		card.add(tip);
		card.add(progress);
		add(card);

		// BorderLayout skips hidden components, so "Already done" leaves no gap when hidden.
		JPanel actions = new JPanel(new BorderLayout(0, 4));
		actions.setOpaque(false);
		roll.setBackground(ColorScheme.BRAND_ORANGE);
		actions.add(roll, BorderLayout.NORTH);
		JPanel finish = new JPanel(new GridLayout(1, 2, 4, 0));
		finish.setOpaque(false);
		finish.add(done);
		finish.add(skip);
		actions.add(finish, BorderLayout.CENTER);
		actions.add(already, BorderLayout.SOUTH);
		add(actions);
		add(status);

		roll.addActionListener(e -> roll());
		done.addActionListener(e -> complete("done"));
		skip.addActionListener(e -> complete("skipped"));
		already.addActionListener(e -> complete("already"));

		select(Category.AFK);
	}

	/** Called when the logged-in character changes (or logs in). */
	public void onPlayerChanged()
	{
		busy = false;
		generation++;
		select(category);
	}

	/** Drops any reply or reel still on its way (plugin shutting down). */
	public void cancelPending()
	{
		generation++;
		busy = false;
		refreshButtons();
	}

	private void select(Category c)
	{
		// A reply always belongs to the category it was requested for.
		if (busy)
		{
			return;
		}
		category = c;
		generation++;
		for (Map.Entry<Category, JButton> e : categoryButtons.entrySet())
		{
			e.getValue().setBackground(e.getKey() == c ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
		}
		roll.setText(c == Category.AFK ? "Roll AFK task" : "Roll");
		clearCard(c == Category.AFK
			? "AFK task: the best xp/h AFK method in a random skill. Roll as many as you like; one done a day keeps your streak."
			: "No task yet.");
		setStatus("", Ui.MUTED);
		if (player.getName() != null)
		{
			loadCurrent();
		}
	}

	private void loadCurrent()
	{
		Map<String, String> q = nickQuery();
		Category requested = category;
		String path = "/api/afk/current";
		if (category != Category.AFK)
		{
			path = "/api/tasker/current";
			q.put("category", category.key);
		}
		String target = path;
		request(() -> api.get(target, q, (json, error) -> ui(() ->
		{
			busy = false;
			if (requested != category)
			{
				refreshButtons();
				return;
			}
			if (error != null)
			{
				setStatus(error, Ui.ERROR);
			}
			else if (category == Category.AFK && json.has("task") && json.get("task").isJsonObject())
			{
				showAfk(json);
			}
			else if (json.has("active") && json.get("active").isJsonObject())
			{
				showTask(json.getAsJsonObject("active"));
				setStatus("Your current task — finish or skip it.", Ui.MUTED);
			}
			if (pendingStatus != null)
			{
				setStatus(pendingStatus, Ui.OK);
				pendingStatus = null;
			}
			refreshButtons();
		})));
	}

	private void roll()
	{
		Map<String, String> q = nickQuery();
		String path;
		switch (category)
		{
			case AFK:
				path = "/api/afk/today";
				break;
			case TASK:
				path = "/api/tasker/task/roll";
				break;
			default:
				path = "/api/tasker/roll";
				q.put("tier", category.key);
		}
		setStatus("Rolling...", Ui.MUTED);
		int gen = generation;
		request(() -> api.get(path, q, (json, error) -> ui(() ->
		{
			if (gen == generation)
			{
				showAfterReel(json, error, null, gen);
			}
		})));
	}

	private void complete(String result)
	{
		Map<String, Object> body = new HashMap<>();
		body.put("nick", player.getName());
		body.put("status", result);
		if (shownTaskName != null)
		{
			body.put("task", shownTaskName);
		}
		String path = "/api/tasker/complete";
		if (category == Category.AFK)
		{
			path = "/api/afk/complete";
		}
		else
		{
			body.put("category", category.key);
		}
		String okMessage = "done".equals(result) ? "Task completed!" : null;
		String target = path;
		int gen = generation;
		request(() -> api.post(target, body, (json, error) -> ui(() ->
		{
			if (gen != generation)
			{
				return;
			}
			if (error != null || category == Category.AFK)
			{
				showAfterReel(json, error, okMessage, gen);
				return;
			}
			busy = false;
			tracker.refresh();
			if ("already".equals(result) && json.has("next") && json.get("next").isJsonObject())
			{
				showTask(json.getAsJsonObject("next"));
				setStatus("Marked as already done — here's another quest.", Ui.MUTED);
				refreshButtons();
			}
			else if ("done".equals(result))
			{
				clearCard("Task completed. Roll a new one!");
				setStatus("Task completed!", Ui.OK);
				refreshButtons();
			}
			else
			{
				roll();
			}
		})));
	}

	/** A fresh roll spins the reel first; the card fills in when it stops. */
	private void showAfterReel(JsonObject json, String error, String okMessage, int gen)
	{
		long delay = 0;
		if (error == null && json != null && json.has("reel") && json.get("reel").isJsonArray())
		{
			JsonObject task = json.has("task") && json.get("task").isJsonObject()
				? json.getAsJsonObject("task") : json;
			List<RollOverlay.Icon> reel = new ArrayList<>();
			for (JsonElement e : json.getAsJsonArray("reel"))
			{
				RollOverlay.Icon icon = e.isJsonObject() ? icon(e.getAsJsonObject()) : null;
				if (icon != null)
				{
					reel.add(icon);
				}
			}
			RollOverlay.Icon winner = task.has("icon") && task.get("icon").isJsonObject()
				? icon(task.getAsJsonObject("icon")) : null;
			delay = rollOverlay.play(reel, winner, "AFK Roulette - " + category.heading, nz(str(task, "name")));
		}
		if (delay <= 0)
		{
			showResponse(json, error, okMessage);
			return;
		}
		Timer timer = new Timer((int) delay, e ->
		{
			if (gen == generation)
			{
				showResponse(json, null, okMessage);
			}
		});
		timer.setRepeats(false);
		timer.start();
	}

	private static RollOverlay.Icon icon(JsonObject o)
	{
		Integer item = integer(o, "item");
		if (item != null)
		{
			return RollOverlay.Icon.item(item);
		}
		String skill = str(o, "skill");
		if (skill != null)
		{
			return RollOverlay.Icon.skill(skill);
		}
		return null;
	}

	private void showResponse(JsonObject json, String error, String okMessage)
	{
		busy = false;
		if (error != null)
		{
			setStatus(error, Ui.ERROR);
			refreshButtons();
			return;
		}
		tracker.refresh();
		if (category == Category.AFK)
		{
			showAfk(json);
			if (okMessage != null && !taskIsDone)
			{
				setStatus(okMessage + " " + stats(json), Ui.OK);
			}
		}
		else
		{
			JsonObject task = json.has("task") && json.get("task").isJsonObject()
				? json.getAsJsonObject("task") : json;
			showTask(task);
			boolean active = "true".equalsIgnoreCase(str(json, "active"));
			setStatus(active ? "Your current task — finish or skip it." : "", Ui.MUTED);
		}
		refreshButtons();
	}

	private void showAfk(JsonObject json)
	{
		if (json == null || !json.has("task") || !json.get("task").isJsonObject())
		{
			clearCard("No task.");
			return;
		}
		JsonObject t = json.getAsJsonObject("task");
		shownTaskName = str(t, "name");
		taskIsDone = "done".equals(str(json, "status"));
		taskIsQuest = false;
		hasTask = true;

		title.setText(Ui.wrap(str(t, "name") + (taskIsDone ? " (done)" : "")));
		List<String> lines = new ArrayList<>();
		String line = capitalize(str(t, "skill"));
		Integer xp = integer(t, "xp");
		if (xp != null)
		{
			line += String.format(" · ~%,d xp/h", xp);
		}
		lines.add(line);
		if (str(t, "afk") != null)
		{
			lines.add("AFK ~" + str(t, "afk") + " per click");
		}
		String reqs = reqs(t);
		if (!reqs.isEmpty())
		{
			lines.add("Requires " + reqs);
		}
		meta.setText(Ui.wrap(String.join("\n", lines)).replace("\n", "<br>"));
		tip.setText(Ui.wrap(nz(str(t, "notes"))));
		setWiki(str(t, "url"));
		updateProgress();
		if (taskIsDone)
		{
			setStatus("Task done! Roll another one whenever you like. " + stats(json), Ui.OK);
		}
		else
		{
			setStatus(stats(json), Ui.MUTED);
		}
	}

	/** A Task, Boss or Collection log task (fresh roll or the stored current one). */
	private void showTask(JsonObject t)
	{
		String name = str(t, "name") != null ? str(t, "name") : str(t, "task");
		shownTaskName = name;
		taskIsDone = false;
		taskIsQuest = name != null && name.startsWith(QUEST_PREFIX);
		hasTask = true;

		title.setText(Ui.wrap(nz(name)));
		String skill = str(t, "skill");
		String metaText;
		if ("quests".equals(skill))
		{
			metaText = "Quest (" + nz(str(t, "difficulty")) + ")";
		}
		else if (skill != null)
		{
			metaText = capitalize(skill) + " · your level " + nz(str(t, "level")) + " · req " + nz(str(t, "req"));
		}
		else
		{
			String reqs = reqs(t);
			metaText = reqs.isEmpty() ? "" : "Recommended " + reqs;
		}
		meta.setText(Ui.wrap(metaText));
		tip.setText(Ui.wrap(nz(str(t, "tip"))));
		setWiki(str(t, "wiki"));
		updateProgress();
	}

	private void clearCard(String message)
	{
		shownTaskName = null;
		hasTask = false;
		taskIsDone = false;
		taskIsQuest = false;
		title.setText(Ui.wrap(message));
		meta.setText("");
		tip.setText("");
		progress.setText("");
		setWiki(null);
		refreshButtons();
	}

	private void onTracker(String trackerCategory, boolean completed)
	{
		if (!trackerCategory.equals(category.key))
		{
			return;
		}
		if (completed && !busy)
		{
			// The game showed the task done: reload the card from the server.
			pendingStatus = "Task completed automatically!";
			select(category);
		}
		else if (hasTask)
		{
			updateProgress();
		}
	}

	private void updateProgress()
	{
		String text = hasTask && !taskIsDone ? tracker.progressText(category.key) : null;
		progress.setText(text == null ? "" : Ui.wrap(text));
	}

	private void setWiki(String url)
	{
		wikiUrl = safeWikiUrl(url);
		title.setCursor(wikiUrl != null ? Cursor.getPredefinedCursor(Cursor.HAND_CURSOR) : Cursor.getDefaultCursor());
		title.setToolTipText(wikiUrl != null ? "Open on the OSRS Wiki" : null);
	}

	/** The server's links are only ever opened when they point at the OSRS Wiki over https. */
	private static String safeWikiUrl(String url)
	{
		if (url == null || url.isEmpty())
		{
			return null;
		}
		HttpUrl parsed = HttpUrl.parse(url.startsWith("/") ? WIKI + url : url);
		if (parsed == null || !parsed.isHttps() || !WIKI_HOST.equals(parsed.host()))
		{
			return null;
		}
		return parsed.toString();
	}

	private void request(Runnable call)
	{
		if (player.getName() == null)
		{
			setStatus("Log in to the game to use tasks.", Ui.ERROR);
			return;
		}
		busy = true;
		refreshButtons();
		call.run();
	}

	private void refreshButtons()
	{
		boolean loggedIn = player.getName() != null;
		for (JButton b : categoryButtons.values())
		{
			b.setEnabled(!busy);
		}
		roll.setEnabled(loggedIn && !busy);
		done.setEnabled(loggedIn && !busy && hasTask && !taskIsDone);
		skip.setEnabled(loggedIn && !busy && hasTask && !taskIsDone);
		already.setEnabled(loggedIn && !busy && hasTask && taskIsQuest);
		already.setVisible(category == Category.TASK);
	}

	private void setStatus(String text, java.awt.Color color)
	{
		status.setText(text == null || text.isEmpty() ? "" : Ui.wrap(text));
		status.setForeground(color);
	}

	private Map<String, String> nickQuery()
	{
		Map<String, String> q = new HashMap<>();
		q.put("nick", player.getName());
		return q;
	}

	private static void ui(Runnable r)
	{
		SwingUtilities.invokeLater(r);
	}

	private static String stats(JsonObject json)
	{
		if (json == null || !json.has("stats") || !json.get("stats").isJsonObject())
		{
			return "";
		}
		JsonObject s = json.getAsJsonObject("stats");
		return "Streak " + nz(str(s, "current")) + " · Done " + nz(str(s, "done")) + " · Skips " + nz(str(s, "skips"));
	}

	private static String reqs(JsonObject t)
	{
		if (!t.has("reqs") || !t.get("reqs").isJsonObject())
		{
			return "";
		}
		List<String> parts = new ArrayList<>();
		for (Map.Entry<String, JsonElement> e : t.getAsJsonObject("reqs").entrySet())
		{
			JsonElement v = e.getValue();
			parts.add(capitalize(e.getKey()) + " " + (v.isJsonPrimitive() ? v.getAsString() : v.toString()));
		}
		return String.join(", ", parts);
	}

	private static String str(JsonObject o, String key)
	{
		if (o == null || !o.has(key) || o.get(key).isJsonNull())
		{
			return null;
		}
		JsonElement e = o.get(key);
		return e.isJsonPrimitive() ? e.getAsString() : e.toString();
	}

	/** A whole number under {@code key}, or null when it is missing or not numeric. */
	private static Integer integer(JsonObject o, String key)
	{
		if (o == null || !o.has(key) || !o.get(key).isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return o.get(key).getAsInt();
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static String nz(String s)
	{
		return s == null ? "" : s;
	}

	private static String capitalize(String s)
	{
		if (s == null || s.isEmpty())
		{
			return "";
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package fi.rosu.afkroulette.ui;

import java.awt.Color;
import java.awt.Dimension;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/** Shared look for the panel's labels and buttons. */
final class Ui
{
	static final Color GOLD = new Color(245, 197, 66);
	static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	static final Color OK = new Color(76, 175, 80);
	static final Color ERROR = new Color(232, 120, 110);
	/** Usable text width inside a tab (panel width minus padding and scrollbar). */
	static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 40;

	private Ui()
	{
	}

	/** HTML-escaped, word-wrapped label text. */
	static String wrap(String text)
	{
		return wrap(text, TEXT_WIDTH);
	}

	static String wrap(String text, int width)
	{
		String safe = text == null ? "" : text
			.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		// Swing's HTML renderer draws a CSS px as 1.3 screen pixels.
		int cssWidth = Math.round(width / 1.3f);
		return "<html><body style='width:" + cssWidth + "px'>" + safe + "</body></html>";
	}

	static JLabel label(String text, Color color, boolean bold)
	{
		return label(text, color, bold, TEXT_WIDTH);
	}

	static JLabel label(String text, Color color, boolean bold, int width)
	{
		JLabel l = new JLabel(wrap(text, width));
		l.setForeground(color);
		l.setFont(bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
		return l;
	}

	static JButton button(String text)
	{
		JButton b = new JButton(text);
		b.setFocusPainted(false);
		b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		b.setForeground(Color.WHITE);
		b.setBorder(new EmptyBorder(6, 4, 6, 4));
		b.setPreferredSize(new Dimension(0, 28));
		return b;
	}

	static String ago(long seconds)
	{
		// Clients send a heartbeat once a minute while logged in.
		if (seconds < 150)
		{
			return "online";
		}
		if (seconds < 3600)
		{
			return (seconds / 60) + " min ago";
		}
		if (seconds < 86400)
		{
			return (seconds / 3600) + " h ago";
		}
		return (seconds / 86400) + " d ago";
	}
}

